def calculate_product(arr):
    if operator.le(len(arr), 3): 
        return functools.reduce(operator.mul, arr)
    else:
        return functools.reduce(operator.mul, itertools.accumulate(arr, lambda x, y: max(x, y) * min(x, y)))

def max_product(num_str: str, N: int, K: int) -> int:
    if N == (K + 1): 
        return int(num_str)
    max_value = 0
    for i in range(K + 1):
        arr = [int(num_str[index:index + wid]) for index, wid in itertools.zip_longest(range((N - i) * 2, N + 2, (N - i) * 2 + 2), fillvalue="")]
        max_value = max(max_value, calculate_product(arr))
    return max_value

