def count_passing_ways(n: int, m: int) -> int:
    MOD = 10**9 + 7
    dp = [[0] * 2 for _ in range(n+1)]

    # Base case
    dp[1][0] = 1
    dp[1][1] = 2

    # Fill the DP table
    for i in range(2, n+1):
        for _ in range(2):
            if _ == 0:
                dp[i][0] = (dp[i-1][1] + dp[i-1][0]) % MOD
            else:
                dp[i][1] = (dp[i-1][0] + dp[i-1][1]) % MOD

    # The result is the sum of all even dp values after m passes
    result = dp[n][0]
    for _ in range(m):
        result = (result * 2) % MOD

    return result

