def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Helper function to find the maximum sum of importance values that can be achieved within a budget
    def knapsack(price_list, importance_list, capacity) -> int:
        num_items = len(price_list)
        dp = [[0] * (capacity + 1) for _ in range(num_items + 1)]

        for i in range(1, num_items + 1):
            price, importance = price_list[i-1], importance_list[i-1]
            for j in range(1, capacity + 1):
                if price <= j:
                    dp[i][j] = max(importance + dp[i-1][j-price], dp[i-1][j])
                else:
                    dp[i][j] = dp[i-1][j]

        return dp[num_items][capacity]

    # 0/1 Knapsack problem for both price and importance values
    max_price = knapsack([item[0] for item in items], [item[1] for item in items], n)
    max_importance = knapsack([item[0] for item in items], [item[1] for item in items], 1000 - max_price)

    return max(max_price, max_importance)

def max_energy(beads):
    n = len(beads)
    dp = [0] * n

    # Bottom-up dynamic programming to find the maximum energy
    for i in range(n):
        for j in range(i):
            if beads[i] == beads[j]:
                dp[i] = max(dp[i], dp[j] + beads[i] * beads[j])

    # The maximum energy is the maximum value in the dp array
    return max(dp)

