def decode(encoded, original, message):
    # Mapping to store encoded to original characters
    decode_dict = {}
    # Mapping to store original to encoded characters
    encode_dict = {}

    # Initialize decoding dictionary
    for i in range(min(len(encoded), len(original))):
        decode_dict[encoded[i]] = original[i]
        encode_dict[original[i]] = encoded[i]

    # Create a set to ensure all characters are represented in both mappings
    chars = set(decode_dict) | set(encode_dict)

    # Check for matching characters in both mappings
    if len(chars) != len(decode_dict):
        return "Failed"

    # Decode the message
    decoded_message = ""
    for char in message:
        if char in decode_dict:
            decoded_message += decode_dict[char]
        elif char in encode_dict:
            decoded_message += encode_dict[char]
        else:
            return "Failed"

    return decoded_message

