def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize the total volume and volume array
    total_volume = sum(volumes)
    volume_array = [0] * (total_volume + 1)

    # Fill the volume array using dynamic programming
    j = n - 1
    while j >= 0:
        for i in range(total_volume, volumes[j] - 1, -1):
            if volume_array[i] >= abs(volumes[j]):
                volume_array[i] += volumes[j]

        j -= 1

    # Find the maximum volume that can be occupied
    max_occupied = 0
    for j in range(len(volume_array)):
        if volume_array[j] >= V:
            max_occupied = max(max_occupied, j)

    # Calculate the minimum remaining space
    min_remaining = total_volume - max_occupied

    return min_remaining

