def min_groups(w, n, prices):
    groups = []
    prices.sort(reverse=True)
    total_price = 0
    for price in prices:
        if total_price + price <= w:
            total_price += price
            groups.append([price])
        else:
            break
    return len(groups)

def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        return 0

    min_moves = 0

    # Calculate the total moves using the known recursive relation for the double-disc Hanoi Towers
    for i in range(1, n + 1):
        min_moves += 3 * ((2 ** i) - 1)

    return min_moves
